PRAGMA foreign_keys=ON;
CREATE TABLE release(release_id TEXT PRIMARY KEY, schema_version TEXT NOT NULL, pipeline_version TEXT NOT NULL, input_manifest_json TEXT NOT NULL);
CREATE TABLE evidence(evidence_id TEXT PRIMARY KEY, source_uri TEXT NOT NULL, source_version TEXT NOT NULL, locator TEXT NOT NULL, verification_status TEXT NOT NULL, rights_status TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE concept(concept_id TEXT PRIMARY KEY, identity_namespace TEXT NOT NULL, identity_key TEXT NOT NULL, semantic_type TEXT NOT NULL, definition TEXT NOT NULL, definition_status TEXT NOT NULL, include_note TEXT NOT NULL, exclude_note TEXT NOT NULL, editorial_note TEXT NOT NULL, facets_json TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN('public','private')), UNIQUE(identity_namespace,identity_key));
CREATE TABLE label(label_id TEXT PRIMARY KEY, concept_id TEXT NOT NULL REFERENCES concept, language TEXT NOT NULL CHECK(language IN('ko','en')), original_text TEXT NOT NULL, normalized_text TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('preferred','alternate','hidden')), terminology_status TEXT NOT NULL CHECK(terminology_status IN('official_source','source_reported','project_source_verified','project_provisional')), review_status TEXT NOT NULL, evidence_id TEXT NOT NULL REFERENCES evidence, rights_status TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN('public','private')), reviewer TEXT, translator TEXT);
CREATE UNIQUE INDEX one_preferred_per_language ON label(concept_id,language) WHERE role='preferred';
CREATE INDEX label_retrieval ON label(language,normalized_text);
CREATE TABLE source_record(record_id TEXT PRIMARY KEY, concept_id TEXT NOT NULL REFERENCES concept, source_namespace TEXT NOT NULL, native_id TEXT NOT NULL, source_version TEXT NOT NULL, raw_record_json TEXT NOT NULL, raw_record_sha256 TEXT NOT NULL, evidence_id TEXT NOT NULL REFERENCES evidence, visibility TEXT NOT NULL CHECK(visibility IN('public','private')));
CREATE TABLE mapping(mapping_id TEXT PRIMARY KEY, subject_id TEXT NOT NULL REFERENCES concept, predicate_id TEXT NOT NULL CHECK(predicate_id IN('skos:exactMatch','skos:closeMatch','skos:broadMatch','skos:narrowMatch','skos:relatedMatch')), object_id TEXT NOT NULL REFERENCES concept, status TEXT NOT NULL CHECK(status IN('source_verified','candidate','conflict','revoked')), justification TEXT NOT NULL, evidence_id TEXT NOT NULL REFERENCES evidence, subject_source_version TEXT NOT NULL, object_source_version TEXT NOT NULL, mapping_tool TEXT NOT NULL, creator_id TEXT NOT NULL, reviewer_id TEXT, mapping_date TEXT NOT NULL, visibility TEXT NOT NULL CHECK(visibility IN('public','private')), decision_json TEXT NOT NULL, CHECK(subject_id<>object_id), CHECK(predicate_id<>'skos:exactMatch' OR status IN('source_verified','revoked')));
CREATE TABLE review_item(review_id TEXT PRIMARY KEY, kind TEXT NOT NULL, subject_id TEXT REFERENCES concept, object_id TEXT REFERENCES concept, status TEXT NOT NULL, reason TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE change_event(event_id TEXT PRIMARY KEY, release_id TEXT NOT NULL REFERENCES release, action TEXT NOT NULL CHECK(action IN('add_mapping','revoke_mapping','change_preference')), target_id TEXT NOT NULL, previous_json TEXT, current_json TEXT NOT NULL, reviewer_id TEXT);
